/* ROOT LAYOUT — the only place <html> and <body> may appear, and it wraps every route.
   The nav is generated from app/_lib/topics.ts, so adding a topic there adds it here.

   ⚠️ This file must exist at app/layout.tsx. Remove it and give each route group its own
      root layout, and navigating BETWEEN groups becomes a full page reload (routing sheet,
      Gotcha 5). */

import "./globals.css";
import Link from "next/link";
import { readyTopics } from "./_lib/topics";

// LayoutProps is a global helper generated by `next dev` / `next build` / `next typegen`:
// no import, and `params` + `children` are typed from the folder structure.
export default function RootLayout({ children }: LayoutProps<"/">) {
  return (
    <html lang="en">
      <body>
        <nav className="topnav">
          <Link href="/">Home</Link>
          {readyTopics.map((t) => (
            <Link key={t.slug} href={`/${t.slug}`}>{t.title}</Link>
          ))}
          {/* A plain <a> works too, but it is a FULL page load: every layout remounts and all
              client state is lost. <Link> does a client-side navigation and keeps layouts alive. */}
        </nav>
        <main>{children}</main>
      </body>
    </html>
  );
}
